SET LOCAL ROLE postgres;
INSERT INTO public.preconsult_brief_versions (id,clinic_id,patient_id,origin_patient_id,consultation_id,version_number,source_watermark,source_manifest,selection_contract_version,brief_schema_version,generator_version,generation_fingerprint,result_state,payload) VALUES ('e5600000-0000-4000-8000-000000000002','e5000000-0000-4000-8000-000000000001','e5200000-0000-4000-8000-000000000001','e5200000-0000-4000-8000-000000000001','e5300000-0000-4000-8000-000000000001',2,repeat('c',64),'{}','p12/v1','p12/v1','p12/v1',repeat('d',64),'ready','{}');
