SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e5100000-0000-4000-8000-000000000001',true);
SELECT is((SELECT brief_version_id FROM public.preconsult_brief_start_snapshots WHERE consultation_id='e5300000-0000-4000-8000-000000000001'),'e5600000-0000-4000-8000-000000000001'::uuid,'newer persisted brief B cannot replace captured A');
